mapper.select:
SELECT COUNT(*) FROM `order`
WHERE status IN (1, 5)
  AND create_time >= #{start} AND create_time < #{end}

SELECT COUNT(*) FROM `order`
WHERE status = 0
  AND create_time >= #{start} AND create_time < #{end}

SELECT COALESCE(SUM(refund_amount), 0)
FROM `order`
WHERE create_time >= #{start} AND create_time < #{end}

SELECT COUNT(*) FROM `order`
WHERE status IN (3, 4, 5)
  AND create_time >= #{start} AND create_time < #{end}

SELECT s.id AS showId, s.name AS showName, c.name AS categoryName, ct.name AS cityName, COALESCE(rev.orderCount, 0) AS orderCount, COALESCE(tic.cnt, 0) AS ticketCount, COALESCE(rev.amt, 0) AS revenue, COALESCE(rev.refundAmt, 0) AS refundAmount FROM `show` s LEFT JOIN category c ON c.id = s.category_id LEFT JOIN city ct ON ct.code = s.city_code LEFT JOIN ( SELECT ss.show_id, COUNT(o.id) AS orderCount, SUM(o.total_amount) AS amt, SUM(o.refund_amount) AS refundAmt FROM `order` o JOIN show_session ss ON ss.id = o.session_id WHERE o.status IN (1, 5) AND o.create_time >= #{start} AND o.create_time < #{end} GROUP BY ss.show_id ) rev ON rev.show_id = s.id LEFT JOIN ( SELECT ss.show_id, COUNT(oi.id) AS cnt FROM order_item oi JOIN `order` o ON o.id = oi.order_id JOIN show_session ss ON ss.id = o.session_id WHERE o.status IN (1, 5) AND o.create_time >= #{start} AND o.create_time < #{end} GROUP BY ss.show_id ) tic ON tic.show_id = s.id WHERE rev.orderCount IS NOT NULL ORDER BY
ticketCount DESC orderCount DESC revenue DESC
LIMIT #{limit}

SELECT ss.id AS sessionId, s.name AS showName, ss.name AS sessionName, ss.start_time AS startTime, ss.total_seats AS totalSeats, COALESCE(sold.cnt, 0) AS soldSeats, CASE WHEN ss.total_seats > 0 THEN COALESCE(sold.cnt, 0) / ss.total_seats ELSE 0 END AS fillRate, COALESCE(rev.amt, 0) AS revenue FROM show_session ss JOIN `show` s ON s.id = ss.show_id LEFT JOIN ( SELECT o.session_id, COUNT(t.id) AS cnt FROM ticket t JOIN `order` o ON o.id = t.order_id WHERE t.status IN (0, 1) GROUP BY o.session_id ) sold ON sold.session_id = ss.id LEFT JOIN ( SELECT session_id, SUM(total_amount) AS amt FROM `order` WHERE status IN (1, 5) GROUP BY session_id ) rev ON rev.session_id = ss.id WHERE ss.start_time >= #{start} AND ss.start_time < #{end} AND ss.show_id = #{showId} ORDER BY
revenue DESC ss.start_time ASC fillRate DESC
LIMIT #{limit}

SELECT COUNT(DISTINCT user_id) FROM `order`
WHERE status IN (1, 5)
  AND create_time >= #{start} AND create_time < #{end}

SELECT COUNT(*) FROM `order`
WHERE status = 2 AND cancel_reason = #{reason}
  AND create_time >= #{start} AND create_time < #{end}

SELECT COUNT(*) FROM `order`
WHERE status = #{status}
  AND create_time >= #{start} AND create_time < #{end}
